// Per-character numbers for the shop / inventory tooltips and the "Detalhes" popup: PBCross Character.<name>
// (public/assets/cross/config/character.json, generated by pbx cross-pef: HP, Movement.FrontMoveSpeed, DamageRate per hit part), keyed by ITEMID.
// Display only: the match core takes HP from CharaHealth (gameplay/charaHp.ts); movement and damage rates in battle still
// use the default soldier (pbConfig PB_CHARA), so only HP differs per character there.

export interface CharaStats {
  hp: number;
  /** Movement.FrontMoveSpeed (m/s, running) */
  speed: number;
  /** DamageRate: multiplier of the damage the character takes per hit part */
  damage: { head: number; body: number; arm: number; leg: number };
}

let table: Map<number, CharaStats> | null = null;
let loading: Promise<void> | null = null;

interface PefChara { ITEMID?: number; HP?: number; Movement?: { FrontMoveSpeed?: number }; DamageRate?: Record<string, number> }

/** Tests / Node: the parsed character.json. */
export function setCharaStats(json: { Character?: Record<string, PefChara> } | null): void {
  table = new Map();
  for (const c of Object.values(json?.Character ?? {})) {
    if (!c.ITEMID || !c.HP || !c.DamageRate) continue;
    const d = c.DamageRate;
    table.set(c.ITEMID, { hp: c.HP, speed: c.Movement?.FrontMoveSpeed ?? 0, damage: { head: d.Head ?? 1, body: d.Body ?? 1, arm: d.Arm ?? 1, leg: d.Leg ?? 1 } });
  }
}

/** Browser: fetch once (1.7 MB, the whole Character table); a failed fetch leaves the tooltips with HP only. */
export function loadCharaStats(base = "/assets/cross/config"): Promise<void> {
  return (loading ??= fetch(`${base}/character.json`)
    .then((r) => (r.ok ? r.json() : null))
    .then((j: { Character?: Record<string, PefChara> } | null) => { if (j) setCharaStats(j); })
    .catch(() => { loading = null; }));
}

export function charaStats(itemId: number): CharaStats | undefined {
  return table?.get(itemId);
}
